-- Import all 9,994 Superstore records. Run once after 01_database_setup.sql.
-- Creates sales_raw_complete; existing tables are preserved.
USE sales_analysis;
CREATE TABLE sales_raw_complete (
  `Row ID` INT NOT NULL PRIMARY KEY,
  `Order ID` TEXT,
  `Order Date` TEXT,
  `Ship Date` TEXT,
  `Ship Mode` TEXT,
  `Customer ID` TEXT,
  `Customer Name` TEXT,
  `Segment` TEXT,
  `Country` TEXT,
  `City` TEXT,
  `State` TEXT,
  `Postal Code` TEXT,
  `Region` TEXT,
  `Product ID` TEXT,
  `Category` TEXT,
  `Sub-Category` TEXT,
  `Product Name` TEXT,
  `Sales` DOUBLE,
  `Quantity` INT,
  `Discount` DOUBLE,
  `Profit` DOUBLE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
START TRANSACTION;
COMMIT;
SELECT COUNT(*) AS total_rows, COUNT(DISTINCT `Row ID`) AS unique_row_ids, ROUND(SUM(Sales),2) AS total_sales FROM sales_raw_complete;
